return {Sheet1={["1000"]={id="1000",flag={"23defectstart",2},index=1,text="缘起缘灭，概不由己，何须强留。",time=1},["1001"]={id="1001",flag={"23defectstart",2},index=2,text="道途不同，分歧已定，终是殊途。",time=1},["1002"]={id="1002",flag={"23defectstart",2},index=3,text="拜谢师恩，辞别山门。",time=1},["1003"]={id="1003",flag={"23defectstart",2},index=4,text="江湖新途，前程朗朗。",time=1},["1004"]={id="1004",flag={"23defectstart",2},index=5,text="栖云谷一战后，返回师门复命。",time=1},["1005"]={id="1005",flag={"23defectstart",2},index=6,text="长老将你所为悉数上报，",time=1},["1006"]={id="1006",flag={"23defectstart",2},index=7,text="因行事残虐不仁，你被罚闭关思过。",time=1},["1007"]={id="1007",flag={"23defectstart",2},index=8,text="你心有不服，出言顶撞。",time=1},["1008"]={id="1008",flag={"23defectstart",2},index=9,text="几番争论，数次思过，所行未改，",time=1},["1009"]={id="1009",flag={"23defectstart",2},index=10,text="终是因道途相异，你辞别山门，再踏江湖。",time=1},["2000"]={id="2000",flag={"23defectstart",3},index=1,text="命运未通，被愚人之轻弃。",time=1},["2001"]={id="2001",flag={"23defectstart",3},index=2,text="临难不屈，复得以血还血。",time=1},["2002"]={id="2002",flag={"23defectstart",3},index=3,text="旧恨才消，新愁又起。",time=1},["2003"]={id="2003",flag={"23defectstart",3},index=4,text="百忧难解，隐名山间。",time=1},["2004"]={id="2004",flag={"23defectstart",3},index=5,text="栖云谷一战，你遭小人嫁祸。",time=1},["2005"]={id="2005",flag={"23defectstart",3},index=6,text="先是重光教徒指认，如今死无对证。",time=1},["2006"]={id="2006",flag={"23defectstart",3},index=7,text="再是伪造书信，自你房中搜出。",time=1},["2007"]={id="2007",flag={"23defectstart",3},index=8,text="最后寻得你手下留情放走的重光教徒，",time=1},["2008"]={id="2008",flag={"23defectstart",3},index=9,text="真真假假间将罪名坐实。",time=1},["2009"]={id="2009",flag={"23defectstart",3},index=10,text="你辨无可辨，出走山门，",time=1},["2010"]={id="2010",flag={"23defectstart",3},index=11,text="寻得良机报仇雪恨。",time=1},["2011"]={id="2011",flag={"23defectstart",3},index=12,text="但回山门已是无望，百忧郁结，归隐山间。",time=1},["3000"]={id="3000",flag={"23defectstart",4},index=1,text="人心百态巧且艰，临危利害两相关。",time=1},["3001"]={id="3001",flag={"23defectstart",4},index=2,text="朝为亲戚暮仇敌。",time=1},["3002"]={